/**
 * Admit Card Structure's HTTP service — /api/v2/examination/admit-card-structures. Create,
 * edit and delete need the 'admit-card-structure' edit grant; each save answers 202 + jobId
 * (cards are generated by a background job) and the page follows the job.
 */
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from 'src/environments/environment';
import {
  AdmitStructureDetail, AdmitStructureList, AdmitStructureOptions, AdmitStructurePayload, AdmitStructureSaveResponse
} from 'src/app/shared/models/examination/examination.model';

export interface AdmitStructureFilters {
  search?: string;
  classId?: string;
  streamId?: string;
  groupId?: string;
  sectionId?: string;
}

@Injectable({ providedIn: 'root' })
export class AdmitCardStructureService {
  private url = `${environment.API_URL}/api/v2/examination/admit-card-structures`;

  constructor(private http: HttpClient) {}

  list(adminId: string, session: string, filters: AdmitStructureFilters, page = 1): Observable<AdmitStructureList> {
    const params: Record<string, string> = { adminId, session, page: String(page) };
    Object.entries(filters).forEach(([key, value]) => { if (value) params[key] = String(value); });
    return this.http.get<AdmitStructureList>(this.url, { params });
  }

  options(adminId: string, session: string, classId: string, streamId: string, groupId: string): Observable<AdmitStructureOptions> {
    return this.http.get<AdmitStructureOptions>(`${this.url}/options`, { params: { adminId, session, classId, streamId, groupId } });
  }

  get(adminId: string, id: string): Observable<AdmitStructureDetail> {
    return this.http.get<AdmitStructureDetail>(`${this.url}/${id}`, { params: { adminId } });
  }

  create(adminId: string, session: string, payload: AdmitStructurePayload): Observable<AdmitStructureSaveResponse> {
    return this.http.post<AdmitStructureSaveResponse>(this.url, { adminId, session, ...payload });
  }

  update(adminId: string, session: string, id: string, payload: AdmitStructurePayload): Observable<AdmitStructureSaveResponse> {
    return this.http.put<AdmitStructureSaveResponse>(`${this.url}/${id}`, { adminId, session, ...payload });
  }

  remove(adminId: string, id: string): Observable<{ message: string; cardsRemoved: number }> {
    return this.http.delete<{ message: string; cardsRemoved: number }>(`${this.url}/${id}`, { params: { adminId } });
  }
}
